contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newOwner, address nonOwner) public payable {
        require(nonOwner != address(this));

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool nonOwnerReverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            nonOwnerReverted = true;
        } else {
            nonOwnerReverted = false;
        }

        address ownerAfterNonOwnerAttempt = c.owner(); if (__ESBMC_reverted()) return;

        bool ownerReverted;
        c.transferOwnership(newOwner); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            ownerReverted = true;
        } else {
            ownerReverted = false;
        }

        address ownerAfterOwnerAttempt = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            (nonOwnerReverted && ownerAfterNonOwnerAttempt == ownerBefore) ||
            (ownerReverted && ownerAfterOwnerAttempt == newOwner && !nonOwnerReverted)
        );
    }
}

